function storageItems(){return [{id:"pages",nameKey:"storage.itemWorks",keys:[STORAGE_KEY],defaultOn:true},{id:"draft",nameKey:"storage.itemDraft",keys:["p5_gen_draft"],defaultOn:true},{id:"settings",nameKey:"storage.itemSettings",keys:[THEME_KEY,LANG_KEY,SETTINGS_KEY],defaultOn:true},{id:"keys",nameKey:"storage.itemKeys",keys:[AI_KEY_STORAGE],defaultOn:false},{id:"prompts",nameKey:"storage.itemPrompts",keys:[AI_PROMPT_STORAGE],defaultOn:true},{id:"customModels",nameKey:"storage.itemCustomModels",keys:[AI_CUSTOM_MODELS_STORAGE],defaultOn:true},{id:"currentModel",nameKey:"storage.itemCurrentModel",keys:[AI_CURRENT_MODEL_STORAGE],defaultOn:true},{id:"chats",nameKey:"storage.itemChats",dynamic:"chats",defaultOn:true}];}
