function _writeItemsToZip(zip,selected){var ik=selected.map(function(it){return it.dynamic==="chats"?"p5_ai_chats":it.keys[0];});zip.file("manifest.json",JSON.stringify({app:"randomArt",schemaVersion:1,exportedAt:new Date().toISOString(),items:ik},null,2));selected.forEach(function(item){if(item.dynamic==="chats"){var cm={};getAllModels().forEach(function(m){var v=storageGet(AI_CHAT_STORAGE+"_"+m.id,null);if(v&&v.length)cm[m.id]=v;});zip.file("p5_ai_chats.json",JSON.stringify(cm,null,2));return;}if(item.id==="settings"){var s={theme:storageGet(THEME_KEY,"light"),lang:storageGet(LANG_KEY,""),settings:storageGet(SETTINGS_KEY,null)};zip.file("p5_settings.json",JSON.stringify(s,null,2));return;}var v=storageGet(item.keys[0],null);if(v==null)return;zip.file(item.keys[0]+".json",JSON.stringify(v,null,2));});}
