function parseBackupFile(file){return new Promise(function(resolve,reject){var r=new FileReader();r.onload=function(e){var buf=e.target.result;var isZip=false;try{var arr=new Uint8Array(buf,0,4);isZip=arr[0]===0x50&&arr[1]===0x4b;}catch(err){}if(isZip){window.JSZip.loadAsync(buf).then(function(zip){var tasks=[];var known=["p5_pages.json","p5_gen_draft.json","p5_settings.json","p5_ai_keys.json","p5_ai_prompts.json","p5_ai_custom_models.json","p5_ai_current_model.json","p5_ai_chats.json"];var res={source:file.name,files:{},manifest:null};if(zip.file("manifest.json")){tasks.push(zip.file("manifest.json").async("string").then(function(txt){try{res.manifest=JSON.parse(txt);}catch(e){}}));}known.forEach(function(fn){var f=zip.file(fn);if(!f)return;tasks.push(f.async("string").then(function(txt){try{res.files[fn]=JSON.parse(txt);}catch(e){}}));});return Promise.all(tasks).then(function(){resolve(res);});}).catch(reject);return;}try{var txt=new TextDecoder("utf-8").decode(new Uint8Array(buf));var obj=JSON.parse(txt);if(obj&&Array.isArray(obj.messages)){reject(new Error("AI_CHAT_JSON"));return;}reject(new Error("UNRECOGNIZED_JSON"));}catch(err){reject(new Error("BAD_JSON"));}};r.onerror=reject;r.readAsArrayBuffer(file);});}
